/* Seeded listings ship without photos; give each one a scene matching its
   type so Browse looks like a real marketplace instead of emoji tiles.
   Host-uploaded photos always win — this only fills the gaps. */

const TYPE_SCENES = {
  'Covered Garage':   [SAMPLE_PHOTOS.garage, SAMPLE_PHOTOS.parkade, SAMPLE_PHOTOS.gated, SAMPLE_PHOTOS.openlot],
  'Open Lot':         [SAMPLE_PHOTOS.openlot, SAMPLE_PHOTOS.gated, SAMPLE_PHOTOS.street, SAMPLE_PHOTOS.parkade],
  'Private Driveway': [SAMPLE_PHOTOS.driveway, SAMPLE_PHOTOS.garage, SAMPLE_PHOTOS.street, SAMPLE_PHOTOS.openlot],
  'Street Parking':   [SAMPLE_PHOTOS.street, SAMPLE_PHOTOS.openlot, SAMPLE_PHOTOS.driveway, SAMPLE_PHOTOS.gated],
  'Gated Lot':        [SAMPLE_PHOTOS.gated, SAMPLE_PHOTOS.parkade, SAMPLE_PHOTOS.garage, SAMPLE_PHOTOS.openlot],
};

function withSamplePhotos(spot, i){
  if(spot.photos && spot.photos.length) return spot;
  const scenes = TYPE_SCENES[spot.type] || [SAMPLE_PHOTOS.openlot, SAMPLE_PHOTOS.garage, SAMPLE_PHOTOS.street, SAMPLE_PHOTOS.gated];
  // rotate so neighbouring cards of the same type don't lead with the same photo
  const shift = i % scenes.length;
  const ordered = [...scenes.slice(shift), ...scenes.slice(0, shift)];
  return {...spot, photos: ordered};
}

const SEEDED_SPOTS = INITIAL_SPOTS.map(withSamplePhotos);

const AREAS = ['All Areas', ...Array.from(new Set(INITIAL_SPOTS.map(s=>s.area)))];

/* ---------- HELPERS ---------- */

function avgRating(spot){
  if(!spot.reviews || spot.reviews.length===0) return null;
  const sum = spot.reviews.reduce((a,r)=>a+r.rating,0);
  return (sum/spot.reviews.length);
}
function fmtRating(spot){
  const r = avgRating(spot);
  return r===null ? null : r.toFixed(1);
}
function stars(n){
  const full = Math.round(n);
  return '★★★★★'.slice(0,full) + '☆☆☆☆☆'.slice(0, 5-full);
}
function gmapsDirections(lat,lng,label){
  return `https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}&destination_place_id=&travelmode=driving`;
}
function gmapsView(lat,lng){
  return `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
}
function uid(prefix){ return prefix + Math.random().toString(36).slice(2,9); }

/* ---------- PHOTO HANDLING ----------
   Phone photos are 3-8MB; localStorage caps out around 5MB total.
   Every upload is downscaled to <=1200px and re-encoded as JPEG so a
   stored photo lands near 100-150KB instead of megabytes. */

const MAX_PHOTOS = 5;
const MAX_EDGE = 1200;

function compressImage(file){
  return new Promise((resolve,reject)=>{
    if(!file.type.startsWith('image/')){ reject(new Error('Not an image')); return; }
    const reader = new FileReader();
    reader.onerror = ()=>reject(new Error('Could not read file'));
    reader.onload = ()=>{
      const img = new Image();
      img.onerror = ()=>reject(new Error('Could not decode image'));
      img.onload = ()=>{
        let {width:w, height:h} = img;
        if(w>MAX_EDGE || h>MAX_EDGE){
          const scale = MAX_EDGE / Math.max(w,h);
          w = Math.round(w*scale); h = Math.round(h*scale);
        }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff';           // flatten transparency so PNGs don't go black
        ctx.fillRect(0,0,w,h);
        ctx.drawImage(img,0,0,w,h);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

/* Storage is shared with everything else we persist, so a failed write
   is a real possibility once a few listings carry photos. */
function saveSpots(spots){
  try {
    localStorage.setItem('parkko_spots', JSON.stringify(spots));
    return {ok:true};
  } catch(err){
    return {ok:false, error:'Storage full — try fewer or smaller photos.'};
  }
}

function loadSpots(){
  try {
    const raw = localStorage.getItem('parkko_spots');
    if(!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.length ? parsed : null;
  } catch(err){
    return null;
  }
}

/* ---------- BOOKER PROFILE & DOCUMENTS ----------
   A booker verifies once by submitting documents; after that, every booking
   skips the document step and the host just sees a "Verified" badge. The
   four documents are all images, so they reuse compressImage(). Plate number
   is the one text field. Persisted under its own localStorage key. */

const DOC_TYPES = [
  {key:'license', label:"Driver's License",       icon:'🪪', kind:'image'},
  {key:'orcr',    label:'OR / CR (vehicle reg.)', icon:'📄', kind:'image'},
  {key:'govid',   label:'Government ID',           icon:'🆔', kind:'image'},
  {key:'vehicle', label:'Vehicle photo',           icon:'🚗', kind:'image'},
];

function loadProfile(){
  try {
    const raw = localStorage.getItem('parkko_profile');
    return raw ? JSON.parse(raw) : {verified:false, name:'', plate:'', docs:{}};
  } catch(err){
    return {verified:false, name:'', plate:'', docs:{}};
  }
}

function saveProfile(profile){
  try {
    localStorage.setItem('parkko_profile', JSON.stringify(profile));
    return {ok:true};
  } catch(err){
    return {ok:false, error:'Storage full — documents are large; try re-taking with lower resolution.'};
  }
}

/* ---------- CHAT ----------
   One thread per spot, keyed by spot id. The "host" is simulated: after a
   booker message, a canned reply lands so the thread feels alive in the demo. */

function loadChats(){
  try {
    const raw = localStorage.getItem('parkko_chats');
    return raw ? JSON.parse(raw) : {};
  } catch(err){
    return {};
  }
}

function loadSaved(){
  try { return JSON.parse(localStorage.getItem('parkko_saved')||'[]'); }
  catch(err){ return []; }
}
function persistSaved(ids){
  try { localStorage.setItem('parkko_saved', JSON.stringify(ids)); } catch(err){}
}

function saveChats(chats){
  try { localStorage.setItem('parkko_chats', JSON.stringify(chats)); return {ok:true}; }
  catch(err){ return {ok:false}; }
}

const HOST_REPLIES = [
  "Hi! Yes, the spot's available — just confirm your booking and message me when you're near.",
  "Thanks for reaching out! Gate code is sent once your booking is confirmed. 🙂",
  "Sure, that works. There's space for an SUV, no problem.",
  "Salamat! I'll keep the slot reserved for you. Let me know your arrival time.",
];

/* ---------- SMALL UI PIECES ---------- */

function PhotoUploader({photos, onChange}){
  const [busy,setBusy] = useState(false);
  const [error,setError] = useState('');
  const inputRef = useRef(null);

  async function handleFiles(e){
    const files = Array.from(e.target.files||[]);
    if(!files.length) return;
    setError(''); setBusy(true);
    const room = MAX_PHOTOS - photos.length;
    if(files.length > room) setError(`Only ${room} more photo${room!==1?'s':''} allowed — extras skipped.`);
    const accepted = [];
    for(const file of files.slice(0, Math.max(room,0))){
      try { accepted.push(await compressImage(file)); }
      catch(err){ setError(`Skipped "${file.name}" — ${err.message}.`); }
    }
    if(accepted.length) onChange([...photos, ...accepted]);
    setBusy(false);
    if(inputRef.current) inputRef.current.value = '';  // allow re-picking the same file
  }

  const full = photos.length >= MAX_PHOTOS;

  return (
    <div>
      <div className="photo-grid">
        {photos.map((src,i)=>(
          <div key={i} className="photo-thumb">
            <img src={src} alt={`Listing photo ${i+1}`} />
            {i===0 && <span className="photo-cover">Cover</span>}
            <button type="button" className="photo-remove"
              onClick={()=>onChange(photos.filter((_,j)=>j!==i))}
              aria-label={`Remove photo ${i+1}`}>✕</button>
          </div>
        ))}
        {!full && (
          <button type="button" className="photo-add" onClick={()=>inputRef.current && inputRef.current.click()} disabled={busy}>
            <span style={{fontSize:26,lineHeight:1}}>{busy?'⏳':'📷'}</span>
            <span>{busy?'Processing…':'Add photos'}</span>
          </button>
        )}
      </div>
      <input ref={inputRef} type="file" accept="image/*" multiple hidden onChange={handleFiles} />
      <p className="muted" style={{fontSize:12,marginTop:6}}>
        {photos.length}/{MAX_PHOTOS} photos · first one is the cover. Photos are resized automatically.
      </p>
      {error && <p style={{fontSize:12,color:'#b91c1c',marginTop:4}}>{error}</p>}
    </div>
  );
}

/* One document = one compressed image. Reuses the same compression path as
   listing photos so we never store a raw multi-MB camera capture. */
function DocUploader({docType, value, onChange}){
  const [busy,setBusy] = useState(false);
  const [error,setError] = useState('');
  const inputRef = useRef(null);

  async function handleFile(e){
    const file = (e.target.files||[])[0];
    if(!file) return;
    setError(''); setBusy(true);
    try { onChange(await compressImage(file)); }
    catch(err){ setError(err.message); }
    setBusy(false);
    if(inputRef.current) inputRef.current.value = '';
  }

  return (
    <div className="doc-row">
      <div className="doc-info">
        <span className="doc-icon">{docType.icon}</span>
        <span className="doc-label">{docType.label}</span>
      </div>
      {value ? (
        <div className="doc-done">
          <img src={value} alt={docType.label} className="doc-thumb" />
          <span className="doc-check">✓ Uploaded</span>
          <button type="button" className="doc-replace" onClick={()=>inputRef.current && inputRef.current.click()}>Replace</button>
        </div>
      ) : (
        <button type="button" className="doc-upload" onClick={()=>inputRef.current && inputRef.current.click()} disabled={busy}>
          {busy ? '⏳ Processing…' : '📎 Upload'}
        </button>
      )}
      <input ref={inputRef} type="file" accept="image/*" hidden onChange={handleFile} />
      {error && <p style={{fontSize:11,color:'#b91c1c',margin:'2px 0 0',flexBasis:'100%'}}>{error}</p>}
    </div>
  );
}

function AmenityPill({k}){
  const a = AMENITY_LABELS[k];
  if(!a) return null;
  return <span className="amenity-pill">{a.icon} {a.label}</span>;
}

function SpotCard({spot, onOpen, saved, onToggleSave}){
  const rating = fmtRating(spot);
  const hasPhotos = spot.photos && spot.photos.length > 0;
  return (
    <div className="card" onClick={()=>onOpen(spot.id)}>
      <div className="card-photo" style={hasPhotos ? undefined : {background:GRADIENTS[spot.gradient % GRADIENTS.length]}}>
        {hasPhotos
          ? <img src={spot.photos[0]} alt={spot.title} loading="lazy" />
          : <span style={{filter:'drop-shadow(0 2px 4px rgba(0,0,0,.25))'}}>{ICONS[spot.icon % ICONS.length]}</span>}
        {spot.reviews.length===0 && <span className="badge-new">New</span>}
        <button className={"card-heart"+(saved?' saved':'')}
          onClick={(e)=>{ e.stopPropagation(); onToggleSave(spot.id); }}
          aria-label={saved?'Remove from saved':'Save spot'}>
          {saved ? '♥' : '♡'}
        </button>
        {hasPhotos && spot.photos.length>1 && <span className="photo-count">📷 {spot.photos.length}</span>}
      </div>
      <div className="card-body">
        <div className="card-titlerow">
          <p className="card-title">{spot.title}</p>
          <span className={"card-rating-inline"+(rating?'':' new')}>
            {rating ? <React.Fragment>★ {rating}</React.Fragment> : 'New'}
          </span>
        </div>
        <p className="card-area">{spot.area} · {spot.type}</p>
        <div className="card-footer">
          <div className="price">₱{spot.price}<span> / hour</span></div>
          <div style={{fontSize:12.5,color:'var(--muted)'}}>₱{rateFor(spot,'month')}/mo</div>
        </div>
      </div>
    </div>
  );
}

/* ---------- BROWSE VIEW ---------- */

function BrowseView({spots, onOpen, savedIds, onToggleSave}){
  const [q,setQ] = useState('');
  const [area,setArea] = useState('All Areas');
  const [sort,setSort] = useState('rating');
  const [heroIdx,setHeroIdx] = useState(0);
  const [typeFilter,setTypeFilter] = useState('All');
  const [maxPrice,setMaxPrice] = useState(100);
  const [activeAmenities,setActiveAmenities] = useState([]);
  const [showFilters,setShowFilters] = useState(false);

  const SPOT_TYPES = ['All','Covered Garage','Open Lot','Private Driveway','Street Parking','Gated Lot'];
  function toggleAmenityFilter(k){
    setActiveAmenities(prev=> prev.includes(k) ? prev.filter(a=>a!==k) : [...prev,k]);
  }
  const activeFilterCount = (typeFilter!=='All'?1:0) + (maxPrice<100?1:0) + activeAmenities.length;

  /* Slow crossfade between Iloilo landmarks; long enough to read as
     atmosphere rather than a carousel demanding attention. */
  useEffect(()=>{
    const t = setInterval(()=>setHeroIdx(i=>(i+1)%HERO_PHOTOS.length), 7000);
    return ()=>clearInterval(t);
  },[]);

  const filtered = useMemo(()=>{
    let list = spots.filter(s=>{
      const matchesArea = area==='All Areas' || s.area===area;
      const text = (s.title+' '+s.area+' '+s.address+' '+s.type).toLowerCase();
      const matchesQ = q.trim()==='' || text.includes(q.trim().toLowerCase());
      const matchesType = typeFilter==='All' || s.type===typeFilter;
      const matchesPrice = s.price <= maxPrice;
      const matchesAmenities = activeAmenities.length===0 || activeAmenities.every(a=>s.amenities.includes(a));
      return matchesArea && matchesQ && matchesType && matchesPrice && matchesAmenities;
    });
    if(sort==='rating'){
      list = list.slice().sort((a,b)=>(avgRating(b)||0)-(avgRating(a)||0));
    } else if(sort==='price-asc'){
      list = list.slice().sort((a,b)=>a.price-b.price);
    } else if(sort==='price-desc'){
      list = list.slice().sort((a,b)=>b.price-a.price);
    } else if(sort==='newest'){
      list = list.slice().reverse();
    }
    return list;
  },[spots,q,area,sort,typeFilter,maxPrice,activeAmenities]);

  return (
    <React.Fragment>
      <div className="hero">
        {HERO_PHOTOS.map((p,i)=>(
          <div key={p.key}
            className={"hero-photo"+(i===heroIdx?' show':'')}
            style={{backgroundImage:`url(${p.src})`}} />
        ))}
        <div className="hero-dots">
          {HERO_PHOTOS.map((p,i)=>(
            <button key={p.key} type="button"
              className={"hero-dot"+(i===heroIdx?' active':'')}
              onClick={()=>setHeroIdx(i)}
              aria-label={`Show ${p.caption}`} />
          ))}
        </div>
        <div className="hero-credit">📍 {HERO_PHOTOS[heroIdx].caption} · {HERO_PHOTOS[heroIdx].credit}</div>
        <h1>Find parking anywhere in Iloilo City</h1>
        <p>Rent a driveway, garage, or lot from a local host — by the hour, day, week, or month. Search by mall, church, campus, or barangay.</p>
        <div className="searchbar">
          <span>🔍</span>
          <input placeholder="Try “Jaro”, “SM City”, “Molo”, “IBP”…" value={q} onChange={e=>setQ(e.target.value)} />
          <button onClick={()=>{}}>Search</button>
        </div>
        <div className="filters">
          {AREAS.map(a=>(
            <button key={a} className={"chip"+(area===a?' active':'')} onClick={()=>setArea(a)}>{a}</button>
          ))}
        </div>
      </div>
      <div className="wrap">
        <div className="toolbar">
          <h2>{filtered.length} spot{filtered.length!==1?'s':''} available</h2>
          <div style={{display:'flex',gap:10,alignItems:'center'}}>
            <button className={"filter-btn"+(activeFilterCount>0?' has':'')} onClick={()=>setShowFilters(v=>!v)}>
              ⚙ Filters{activeFilterCount>0?` · ${activeFilterCount}`:''}
            </button>
            <select value={sort} onChange={e=>setSort(e.target.value)}>
              <option value="rating">Sort: Top rated</option>
              <option value="price-asc">Sort: Price (low to high)</option>
              <option value="price-desc">Sort: Price (high to low)</option>
              <option value="newest">Sort: Newest</option>
            </select>
          </div>
        </div>

        {showFilters && (
          <div className="filter-panel">
            <div className="filter-group">
              <label className="filter-label">Type</label>
              <div className="filter-chips">
                {SPOT_TYPES.map(t=>(
                  <button key={t} className={"fchip"+(typeFilter===t?' active':'')} onClick={()=>setTypeFilter(t)}>{t}</button>
                ))}
              </div>
            </div>
            <div className="filter-group">
              <label className="filter-label">Max price: <b>₱{maxPrice}{maxPrice>=100?'+':''}/hr</b></label>
              <input type="range" min="10" max="100" step="5" value={maxPrice}
                onChange={e=>setMaxPrice(Number(e.target.value))} className="filter-range" />
            </div>
            <div className="filter-group">
              <label className="filter-label">Amenities</label>
              <div className="filter-chips">
                {Object.keys(AMENITY_LABELS).map(k=>(
                  <button key={k} className={"fchip"+(activeAmenities.includes(k)?' active':'')} onClick={()=>toggleAmenityFilter(k)}>
                    {AMENITY_LABELS[k].icon} {AMENITY_LABELS[k].label}
                  </button>
                ))}
              </div>
            </div>
            {activeFilterCount>0 && (
              <button className="filter-clear" onClick={()=>{setTypeFilter('All');setMaxPrice(100);setActiveAmenities([]);}}>Clear all filters</button>
            )}
          </div>
        )}

        {filtered.length===0 ? (
          <div className="empty">No spots match your search. Try another area or keyword.</div>
        ) : (
          <div className="grid">
            {filtered.map(s=><SpotCard key={s.id} spot={s} onOpen={onOpen} saved={savedIds.includes(s.id)} onToggleSave={onToggleSave} />)}
          </div>
        )}
      </div>
    </React.Fragment>
  );
}

/* ---------- MAP VIEW ---------- */

function MapView({spots, onOpen}){
  const mapRef = useRef(null);
  const mapObj = useRef(null);
  const [showRentals,setShowRentals] = useState(true);
  const [showPublic,setShowPublic] = useState(true);
  const [vacancy,setVacancy] = useState(()=>VacancyStore.getAll());

  // A driver taps a level from the popup; store it and refresh.
  function reportVacancy(lotId, level){
    setVacancy(VacancyStore.report(lotId, level));
  }
  // Expose to Leaflet popups (they're raw HTML, not React).
  useEffect(()=>{
    window.__parkkoViewSpot = (id)=> onOpen(id);
    window.__parkkoReport = (lotId, level)=> reportVacancy(lotId, level);
  },[]);

  useEffect(()=>{
    if(!mapRef.current) return;
    const map = L.map(mapRef.current,{scrollWheelZoom:true}).setView([10.7202,122.5621], 14);
    mapObj.current = map;
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{
      attribution:'&copy; OpenStreetMap contributors', maxZoom:19,
    }).addTo(map);

    if(showRentals) spots.forEach(spot=>{
      const icon = L.divIcon({
        className:'', html:`<div class="price-pin">₱${spot.price}/hr</div>`, iconSize:[70,30], iconAnchor:[35,15],
      });
      const marker = L.marker([spot.lat, spot.lng], {icon}).addTo(map);
      const rating = fmtRating(spot);
      marker.bindPopup(`
        <div class="popup-card">
          <h4>${spot.title}</h4>
          <p>📍 ${spot.area} ${rating ? '· ★ '+rating : '· New listing'}</p>
          <button onclick="window.__parkkoViewSpot('${spot.id}')">View details</button>
        </div>`);
    });

    if(showPublic) PUBLIC_LOTS.forEach(lot=>{
      const v = vacancy[lot.id];
      const lvl = v ? VACANCY_LEVELS[v.level] : null;
      const dot = lvl ? lvl.color : '#94a3b8';
      const icon = L.divIcon({
        className:'',
        html:`<div class="public-pin" style="--vac:${dot}"><span>P</span></div>`,
        iconSize:[30,38], iconAnchor:[15,38],
      });
      const marker = L.marker([lot.lat, lot.lng], {icon}).addTo(map);
      const statusLine = lvl
        ? `<p class="vac-status" style="color:${lvl.color}">${lvl.emoji} ${lvl.label}</p>`
        : `<p class="vac-status muted">No recent report</p>`;
      const buttons = Object.entries(VACANCY_LEVELS).map(([k,val])=>
        `<button class="vac-btn" style="border-color:${val.color};color:${val.color}" onclick="window.__parkkoReport('${lot.id}','${k}')">${val.emoji} ${val.label}</button>`
      ).join('');
      marker.bindPopup(`
        <div class="popup-card">
          <h4>🅿️ ${lot.name}</h4>
          <p>📍 ${lot.area} · Free / public</p>
          <p style="font-size:11px;color:#64748b">${lot.note}</p>
          ${statusLine}
          <p style="font-size:11px;font-weight:700;margin-top:6px">How full is it now?</p>
          <div class="vac-btns">${buttons}</div>
        </div>`);
    });

    return ()=>{ map.remove(); mapObj.current=null; };
  },[spots, showRentals, showPublic, vacancy]);

  const reportedCount = Object.keys(vacancy).length;

  return (
    <div className="wrap">
      <div className="toolbar">
        <h2>Parking map</h2>
      </div>
      <div className="map-legend">
        <button className={"legend-toggle"+(showRentals?' on':'')} onClick={()=>setShowRentals(v=>!v)}>
          <span className="legend-swatch rental"></span> Rentals ({spots.length})
        </button>
        <button className={"legend-toggle"+(showPublic?' on':'')} onClick={()=>setShowPublic(v=>!v)}>
          <span className="legend-swatch public"></span> Free / public ({PUBLIC_LOTS.length})
        </button>
        <span className="legend-vac">🟢 open · 🟡 some · 🔴 full{reportedCount>0?` · ${reportedCount} reported`:''}</span>
      </div>
      <div className="map-wrap"><div id="leaflet-map" ref={mapRef}></div></div>
      <p className="muted" style={{marginTop:10,fontSize:13}}>Teal pins are rentals — tap to book. Grey "P" pins are free/public lots (malls, plazas); tap one to see how full it is or report the current status yourself.</p>
    </div>
  );
}

/* ---------- HOST FORM ---------- */

function ListSpotView({onPublish}){
  const [form,setForm] = useState({
    title:'', area:AREAS[1]||'Jaro', address:'', price:'', type:'Private Driveway',
    capacity:'Sedan', description:'', availability:'', amenities:[], photos:[],
  });
  const [done,setDone] = useState(false);

  function toggleAmenity(k){
    setForm(f=>({...f, amenities: f.amenities.includes(k) ? f.amenities.filter(a=>a!==k) : [...f.amenities,k]}));
  }
  function submit(e){
    e.preventDefault();
    if(!form.title || !form.address || !form.price) return;
    const areaCoords = {
      'Jaro':[10.739,122.552],'Mandurriao':[10.711,122.548],'City Proper':[10.696,122.564],
      'La Paz':[10.716,122.565],'Molo':[10.696,122.548],
    };
    const base = areaCoords[form.area] || [10.7202,122.5621];
    const jitter = ()=> (Math.random()-0.5)*0.01;
    const newSpot = {
      id: uid('s'),
      title: form.title, area: form.area, address: form.address,
      lat: base[0]+jitter(), lng: base[1]+jitter(),
      price: Number(form.price)||1, type: form.type, capacity: form.capacity,
      amenities: form.amenities, description: form.description || 'No description provided yet.',
      host:{name:'You (New Host)', initial:'Y', since:'2026'},
      availability: form.availability || 'Flexible — message host',
      icon: Math.floor(Math.random()*ICONS.length), gradient: Math.floor(Math.random()*GRADIENTS.length),
      photos: form.photos,
      reviews:[],
    };
    onPublish(newSpot);
    setDone(true);
    setForm({title:'',area:AREAS[1]||'Jaro',address:'',price:'',type:'Private Driveway',capacity:'Sedan',description:'',availability:'',amenities:[],photos:[]});
    setTimeout(()=>setDone(false),4500);
  }

  return (
    <div className="wrap">
      <div className="panel">
        <h2>List your parking spot</h2>
        <p className="muted">Got a driveway, garage, or extra lot in Iloilo City? Publish it in a minute and start earning — hourly, daily, weekly, or monthly.</p>
        <form onSubmit={submit}>
          <div className="form-row">
            <div className="field">
              <label>Listing title</label>
              <input required value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="e.g. Covered driveway near SM City" />
            </div>
          </div>
          <div className="form-row">
            <div className="field">
              <label>Photos of your spot</label>
              <PhotoUploader photos={form.photos} onChange={photos=>setForm(f=>({...f,photos}))} />
            </div>
          </div>
          <div className="form-row">
            <div className="field">
              <label>Area / District</label>
              <select value={form.area} onChange={e=>setForm({...form,area:e.target.value})}>
                {AREAS.filter(a=>a!=='All Areas').map(a=><option key={a} value={a}>{a}</option>)}
              </select>
            </div>
            <div className="field">
              <label>Street address</label>
              <input required value={form.address} onChange={e=>setForm({...form,address:e.target.value})} placeholder="e.g. Rizal St, Iloilo City" />
            </div>
          </div>
          <div className="form-row">
            <div className="field">
              <label>Price per hour (₱)</label>
              <input required type="number" min="1" value={form.price} onChange={e=>setForm({...form,price:e.target.value})} placeholder="25" />
              {Number(form.price)>0 && (
                <div className="rate-strip">
                  <span>Auto rates: <b>₱{rateFor({price:Number(form.price)},'day')}</b>/day</span>
                  <span>· <b>₱{rateFor({price:Number(form.price)},'week')}</b>/week</span>
                  <span>· <b>₱{rateFor({price:Number(form.price)},'month')}</b>/month</span>
                </div>
              )}
            </div>
            <div className="field">
              <label>Spot type</label>
              <select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}>
                <option>Private Driveway</option>
                <option>Covered Garage</option>
                <option>Open Lot</option>
                <option>Gated Lot</option>
                <option>Street Parking</option>
              </select>
            </div>
            <div className="field">
              <label>Vehicle capacity</label>
              <select value={form.capacity} onChange={e=>setForm({...form,capacity:e.target.value})}>
                <option>Sedan</option>
                <option>Sedan / SUV</option>
                <option>Sedan / SUV / Van</option>
                <option>Motorcycle</option>
              </select>
            </div>
          </div>
          <div className="form-row">
            <div className="field">
              <label>Availability</label>
              <input value={form.availability} onChange={e=>setForm({...form,availability:e.target.value})} placeholder="e.g. Mon–Sun, 6:00 AM – 10:00 PM" />
            </div>
          </div>
          <div className="form-row">
            <div className="field">
              <label>Description</label>
              <textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Tell drivers what makes your spot great…" />
            </div>
          </div>
          <div className="field" style={{marginBottom:18}}>
            <label>Amenities</label>
            <div className="checkrow">
              {Object.entries(AMENITY_LABELS).map(([k,v])=>(
                <label key={k} className="checkitem">
                  <input type="checkbox" checked={form.amenities.includes(k)} onChange={()=>toggleAmenity(k)} />
                  {v.icon} {v.label}
                </label>
              ))}
            </div>
          </div>
          <button className="btn-primary" type="submit">Publish listing</button>
        </form>
        {done && <div className="success-box">✅ Your spot is live! Check the Browse or Map tab to see it.</div>}
      </div>
    </div>
  );
}

