/* ---------- BOOKING MODAL ---------- */

function BookingModal({spot, profile, onClose, onConfirm, onDone, onRequestVerify}){
  const [step,setStep] = useState(1); // 1 details, 2 payment, 3 success
  const [date,setDate] = useState('');
  const [start,setStart] = useState('10:00');
  const [end,setEnd] = useState('12:00');
  const [payMethod,setPayMethod] = useState('gcash');
  const [processing,setProcessing] = useState(false);
  const [ref,setRef] = useState('');
  const [payError,setPayError] = useState('');

  const [planKey,setPlanKey] = useState('hour');
  const [units,setUnits] = useState(1);
  const plan = planByKey(planKey);

  const hours = useMemo(()=>{
    const [sh,sm] = start.split(':').map(Number);
    const [eh,em] = end.split(':').map(Number);
    let diff = (eh*60+em) - (sh*60+sm);
    if(diff<=0) diff = 0;
    return diff/60;
  },[start,end]);

  const qty = planKey==='hour' ? hours : units;
  const unitRate = rateFor(spot, planKey);
  const subtotal = qty * unitRate;
  const fee = subtotal * 0.1;
  const total = subtotal + fee;
  const valid = date && qty>0;

  /* Longer plans book whole days, so the hour pickers only apply to hourly. */
  const endsOn = useMemo(()=>{
    if(planKey==='hour' || !date) return '';
    const days = {day:1, week:7, month:30}[planKey] * units;
    const d = new Date(date+'T00:00:00');
    d.setDate(d.getDate() + days);
    return d.toISOString().slice(0,10);
  },[planKey,units,date]);

  function goPay(){ if(valid) setStep(2); }
  function finishBooking(){
    const bookingRef = 'PK-'+Math.floor(100000+Math.random()*899999);
    setRef(bookingRef);
    setProcessing(false);
    setStep(3);
    onConfirm({
      id:uid('b'), spotId:spot.id, date, start, end, total, ref:bookingRef, method:payMethod,
      plan:planKey, units:qty, endsOn,
    });
  }

  async function confirm(){
    setPayError('');
    setProcessing(true);

    // Real PayMongo test-mode flow for GCash, only when the Worker is configured.
    if (PAYMENTS_LIVE && payMethod==='gcash') {
      try {
        const desc = `ParkKo · ${spot.title} · ${plan.label}`;
        const source = await PayMongo.createSource({ amount: total, type:'gcash', description: desc });
        // Open PayMongo's hosted test checkout in a new tab.
        const win = window.open(source.checkoutUrl, '_blank');
        // Poll until the source becomes chargeable (user authorised) or times out.
        let tries = 0;
        const poll = setInterval(async ()=>{
          tries++;
          try {
            const status = await PayMongo.pollStatus(source.id);
            if (status === 'chargeable') {
              clearInterval(poll);
              await PayMongo.paySource({ sourceId: source.id, amount: total, description: desc });
              if (win && !win.closed) win.close();
              finishBooking();
            } else if (status === 'expired' || status === 'consumed') {
              clearInterval(poll);
              setProcessing(false);
              setPayError('Payment was not completed. Please try again.');
            }
          } catch(e){ /* keep polling */ }
          if (tries > 60) { // ~2 minutes
            clearInterval(poll);
            setProcessing(false);
            setPayError('Payment timed out. Please try again.');
          }
        }, 2000);
      } catch(err){
        setProcessing(false);
        setPayError(err.message || 'Could not start payment.');
      }
      return;
    }

    // Demo path (cash-on-arrival, card, or Worker not configured yet).
    setTimeout(finishBooking, 900);
  }

  return (
    <div className="overlay" onClick={e=>{if(e.target===e.currentTarget) onClose();}}>
      <div className="modal" style={{maxWidth:520}}>
        <button className="modal-close" onClick={onClose}>✕</button>
        <div className="modal-body">
          {step===1 && (
            <React.Fragment>
              <h2>Book: {spot.title}</h2>
              {profile && profile.verified ? (
                <div className="verify-banner ok">✓ Verified booker — no documents needed. The host will see your verified badge.</div>
              ) : (
                <div className="verify-banner warn">
                  📄 This host may ask for documents (license, OR/CR, ID, vehicle photo).
                  {' '}<button type="button" className="link-btn" onClick={onRequestVerify}>Verify once</button> to skip this on every booking.
                </div>
              )}
              <p className="muted">₱{spot.price}/hour · {spot.area}</p>

              <div className="plan-tabs">
                {RATE_PLANS.map(p=>{
                  const save = savingsPct(spot,p.key);
                  return (
                    <button key={p.key} type="button"
                      className={"plan-tab"+(planKey===p.key?' active':'')}
                      onClick={()=>{setPlanKey(p.key); setUnits(1);}}>
                      <span className="plan-name">{p.label}</span>
                      <span className="plan-rate">₱{rateFor(spot,p.key)}{p.suffix}</span>
                      {save>0 && <span className="plan-save">Save {save}%</span>}
                    </button>
                  );
                })}
              </div>

              <div className="form-row" style={{marginTop:14}}>
                <div className="field">
                  <label>{planKey==='hour' ? 'Date' : 'Start date'}</label>
                  <input type="date" value={date} onChange={e=>setDate(e.target.value)} />
                </div>
                {planKey!=='hour' && (
                  <div className="field">
                    <label>Number of {plan.unit}s</label>
                    <input type="number" min="1" max="12" value={units}
                      onChange={e=>setUnits(Math.max(1, Number(e.target.value)||1))} />
                  </div>
                )}
              </div>
              {planKey!=='hour' && endsOn && (
                <p className="muted" style={{fontSize:12,marginTop:-4}}>
                  📅 {units} {plan.unit}{units>1?'s':''} · ends {endsOn}
                </p>
              )}
              {planKey==='hour' && (
              <div className="form-row">
                <div className="field">
                  <label>Start time</label>
                  <input type="time" value={start} onChange={e=>setStart(e.target.value)} />
                </div>
                <div className="field">
                  <label>End time</label>
                  <input type="time" value={end} onChange={e=>setEnd(e.target.value)} />
                </div>
              </div>
              )}
              <div className="price-card" style={{position:'static',marginTop:6}}>
                <div className="price-row">
                  <span>{planKey==='hour' ? `${hours>0?hours.toFixed(1):'0'} hour(s) × ₱${unitRate}` : `${units} ${plan.unit}${units>1?'s':''} × ₱${unitRate}`}</span>
                  <span>₱{subtotal.toFixed(0)}</span>
                </div>
                {planKey!=='hour' && savingsPct(spot,planKey)>0 && (
                  <div className="price-row" style={{color:'#15803d'}}>
                    <span>{plan.label} discount</span>
                    <span>−{savingsPct(spot,planKey)}%</span>
                  </div>
                )}
                <div className="price-row"><span>ParkKo service fee (10%)</span><span>₱{fee.toFixed(0)}</span></div>
                <div className="price-row total"><span>Total</span><span>₱{total.toFixed(0)}</span></div>
              </div>
              {!valid && <p style={{color:'var(--danger)',fontSize:12,marginTop:8}}>
                {planKey==='hour' ? 'Pick a date and make sure end time is after start time.' : 'Pick a start date to continue.'}
              </p>}
              <button className="btn-primary" style={{marginTop:16,width:'100%'}} disabled={!valid} onClick={goPay}>Continue to payment</button>
            </React.Fragment>
          )}
          {step===2 && (
            <React.Fragment>
              <h2>Payment</h2>
              <p className="muted">Total due: <strong>₱{total.toFixed(0)}</strong></p>
              <div className="checkrow" style={{margin:'14px 0'}}>
                <label className="checkitem">
                  <input type="radio" name="pay" checked={payMethod==='gcash'} onChange={()=>setPayMethod('gcash')} /> 📱 GCash
                </label>
                <label className="checkitem">
                  <input type="radio" name="pay" checked={payMethod==='card'} onChange={()=>setPayMethod('card')} /> 💳 Debit / Credit Card
                </label>
                <label className="checkitem">
                  <input type="radio" name="pay" checked={payMethod==='cash'} onChange={()=>setPayMethod('cash')} /> 💵 Pay host on arrival
                </label>
              </div>
              {payMethod==='card' && (
                <div className="form-row">
                  <div className="field"><label>Card number</label><input placeholder="4111 1111 1111 1111" /></div>
                  <div className="field"><label>Expiry</label><input placeholder="MM/YY" /></div>
                  <div className="field"><label>CVC</label><input placeholder="123" /></div>
                </div>
              )}
              {payMethod==='gcash' && !PAYMENTS_LIVE && (
                <div className="form-row"><div className="field"><label>GCash mobile number</label><input placeholder="09XX XXX XXXX" /></div></div>
              )}
              {PAYMENTS_LIVE && payMethod==='gcash' ? (
                <p className="muted" style={{fontSize:12}}>🔒 Secure GCash checkout via PayMongo (test mode — no real charge). A PayMongo window will open to confirm.</p>
              ) : (
                <p className="muted" style={{fontSize:12}}>This is a demo prototype — no real payment is processed.</p>
              )}
              {payError && <p style={{color:'var(--danger)',fontSize:13,marginTop:6}}>{payError}</p>}
              <div style={{display:'flex',gap:10}}>
                <button className="btn-secondary" onClick={()=>setStep(1)} disabled={processing}>Back</button>
                <button className="btn-primary" style={{flex:1}} onClick={confirm} disabled={processing}>
                  {processing? (PAYMENTS_LIVE && payMethod==='gcash' ? 'Waiting for GCash…' : 'Processing…') : `Confirm & Pay ₱${total.toFixed(0)}`}
                </button>
              </div>
            </React.Fragment>
          )}
          {step===3 && (
            <React.Fragment>
              <h2>🎉 Booking confirmed!</h2>
              <div className="success-box">
                <p style={{margin:0,fontWeight:700}}>Reference: {ref}</p>
                <p style={{margin:'6px 0 0'}}>{spot.title}</p>
                <p style={{margin:'2px 0 0'}} className="muted">
                  {planKey==='hour' ? `${date} · ${start}–${end}` : `${date} → ${endsOn} · ${units} ${plan.unit}${units>1?'s':''}`}
                  {' · '}₱{total.toFixed(0)} paid via {payMethod==='gcash'?'GCash':payMethod==='card'?'Card':'Pay on arrival'}
                </p>
              </div>
              <a className="directions-link" href={gmapsDirections(spot.lat,spot.lng)} target="_blank" rel="noopener">🧭 Get Directions in Google Maps</a>
              <button className="btn-primary" style={{marginTop:14,width:'100%'}} onClick={onDone}>Done</button>
            </React.Fragment>
          )}
        </div>
      </div>
    </div>
  );
}

